with filtered as (select id, customer_id, device, browser, started_at, country, initcap(trim(browser)) as browser_title, cast(started_at as date) as started_at_day from sessions where started_at > to_timestamp('2023-11-30 20:00:00')), scored as (select id, customer_id, device, browser, started_at, country, browser_title, started_at_day, row_number() over (partition by device order by started_at_day desc, id) as seq_no, first_value(browser) ignore nulls over (partition by customer_id order by started_at_day, id rows between unbounded preceding and current row) as first_known_browser, row_number() over (order by started_at desc, id) as row_seq from filtered), matched_keys as (select customer_id, id from scored except all select customer_id, id from sessions where country in ('SG', 'UK', 'DE')), kept_rows as (select s.* from scored s join matched_keys k on s.customer_id = k.customer_id and s.id = k.id) select id, device, started_at, country, started_at_day, case when device rlike '^(desktop|tablet)$' then 'GROUP_A' else 'EXTENDED' end as device_zone from kept_rows order by device_zone desc nulls first;
